The initial point is $(0,0)$ and the endpoint is $(3,9)$. Plot them and join with a straight line.
[tikz]
% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[]}
\begin{tikzpicture}[x=1.05cm,y=0.2666667cm,font=\fontsize{10}{12}\selectfont,text=black]
\definecolor{blue}{HTML}{268CFF}
\definecolor{housegrid}{HTML}{CCCCCC}
\draw[housegrid,line width=0.25pt,xstep=1,ystep=3] (0,0) grid (4,12);
\draw[black,->] (0,0)--(4.3,0);
\draw[black,->] (0,0)--(0,13);
\foreach \t in {0,1,2,3,4} \node[below,font=\fontsize{8.5}{10}\selectfont] at (\t,0) {$\t$};
\foreach \d in {3,6,9,12} \node[left,font=\fontsize{8.5}{10}\selectfont] at (0,\d) {$\d$};
\node[below] at (2,-2) {Time (hours)};
\node[rotate=90] at (-1,6) {Distance from start (km)};
\draw[blue,line width=0.8pt] (0,0)--(3,9);
\foreach \t/\d in {0/0,3/9} \fill[blue] (\t,\d) circle (1.5pt);
\end{tikzpicture}
[/tikz]

